    /// <summary>Langue de l'interface : français (texte d'origine), anglais ou espagnol.</summary>
    public static class L
    {
        public static string Code = "fr";   // fr, en, es

        public static void Initialiser(string code)
        {
            if (code == "fr" || code == "en" || code == "es") { Code = code; return; }
            string sys = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
            Code = sys == "fr" || sys == "es" ? sys : sys == "en" ? "en" : "fr";
        }

        /// <summary>Traduit un texte écrit en français dans la langue de l'interface.</summary>
        public static string T(string fr)
        {
            if (Code == "fr" || fr == null) return fr;
            string[] t;
            if (!Table.TryGetValue(fr, out t)) return fr;
            return Code == "en" ? t[0] : t[1];
        }

        /// <summary>Faut-il le pluriel ? En français à partir de 2, en anglais et en espagnol dès que ce n'est pas 1.</summary>
        public static bool Pl(int n) { return Code == "fr" ? n > 1 : n != 1; }

        public static string F(string fr, params object[] a) { return string.Format(T(fr), a); }

